"""Consumer read-only financial review flow, separate from sandbox execution."""
REVIEW_JS = r"""
      titles.review='Your financial inbox';
      const reviewView=view('review','Your bills, receipts and payment claims - reconciled without moving money.');
      const reviewHeading=element('h2','Your financial inbox');
      const reviewStatus=element('p','Upload a bill and its receipt, or paste a payment notice. No provider setup is needed for review.','screen-note');
      reviewStatus.setAttribute('role','status');
      const reviewRefresh=element('button','Refresh my financial inbox','planner');reviewRefresh.type='button';
      const reviewCards=element('div');reviewCards.setAttribute('aria-live','polite');
      reviewView.append(reviewHeading,reviewStatus,reviewRefresh,reviewCards);
      const reviewNav=element('button','Financial inbox');reviewNav.type='button';reviewNav.dataset.screenLink='review';nav.insertBefore(reviewNav,nav.querySelector('[data-screen-link="activity"]'));
      const reviewReasons={RECIPIENT_CONFLICT:'Related documents name different recipients.',AMOUNT_CONFLICT:'Related documents disagree about the total.',POSSIBLE_REPEATED_PAYMENT:'More than one transaction reference is linked to this bill. It may be legitimate; check before paying again.',TOTAL_ARITHMETIC_MISMATCH:'The extracted line totals do not match the stated total.',LINE_ARITHMETIC_MISMATCH:'An extracted quantity times price does not match its line total.',EMBEDDED_INSTRUCTION:'The input contains an instruction aimed at bypassing checks.',CURRENCY_UNCONFIRMED:'The currency is ambiguous; no conversion was guessed.',MISSING_CORE_EVIDENCE:'Some matching details lack supporting quotations.',UNSUPPORTED_AMOUNT_PRECISION:'The amount has unsupported precision.',DUE_DATE_UNCONFIRMED:'The due date could not be confirmed.'};
      const reviewLabels={CONFLICT_REVIEW:'Conflicting evidence - check before paying',RECEIPT_MATCHED_CLAIM:'Bill and supplied receipt match',RECORDED_PAYMENT_CLAIM:'Payment claim recorded',BILL_TO_VERIFY:'Bill needs confirmation',INCOMPLETE_REVIEW:'More details needed'};
      function reviewMoney(amount,currency,scales){if(!Number.isSafeInteger(amount))return 'Amount not confirmed';const scale=scales[currency];return currency+' '+(amount/10**scale).toLocaleString('en-IN',{minimumFractionDigits:scale,maximumFractionDigits:scale});}
      async function refreshReviews(){reviewRefresh.disabled=true;reviewStatus.textContent='Reconciling saved claims. No model call or payment is being made.';
        try{const board=await jsonRequest('/api/friday/reviews');if(board.scope!=='READ_ONLY_FINANCIAL_REVIEW'||board.payment_authorized!==false||board.money_moved!==false)throw new Error('Unexpected review response');reviewCards.replaceChildren();
          reviewStatus.textContent=board.document_count+' saved input'+(board.document_count===1?'':'s')+' · '+board.cases.length+' related case'+(board.cases.length===1?'':'s')+' · document claims, not bank confirmation';
          if(!board.cases.length){reviewCards.append(element('p','Nothing to review yet. Open Documents for your own bill, or Overview for a guided example. Questions in Ask Friday work immediately without adding records.','screen-note'));const start=element('button','Choose a starting task','planner');start.type='button';start.dataset.screenLink='home';reviewCards.append(start);return;}
          const totals=element('div',null,'money-summary');Object.entries(board.unconfirmed_bill_totals).forEach(([currency,amount])=>{const card=element('article',null,'money-stat');card.append(element('span','Unconfirmed bill claims'),element('strong',reviewMoney(amount,currency,board.currency_scales)),element('small','Separate currencies; not your balance or payment permission.'));totals.append(card);});reviewCards.append(totals);
          board.cases.forEach(item=>{const card=element('article',null,'money-section review-case');const tone=item.state==='CONFLICT_REVIEW'?'held':'review';card.dataset.tone=tone;const badge=element('span',reviewLabels[item.state]||'Needs review','status '+tone);const claimRecord=board.documents.find(d=>item.document_ids.includes(d.review_id));const claim=claimRecord?.analysis?.facts;const amountCopy=Number.isSafeInteger(item.amount_minor)?reviewMoney(item.amount_minor,item.currency,board.currency_scales):(claim?.currency_label||'Unknown currency')+' '+(claim?.total||'Not extracted')+' (not confirmed)';card.append(badge,element('h3',item.supplier||'Financial document'));const fields=element('dl',null,'review-case-facts');[['Document reference',item.reference||'Not supplied'],['Claimed amount · not a bank balance',amountCopy]].forEach(([name,value])=>{const pair=element('div');pair.append(element('dt',name),element('dd',value));fields.append(pair);});const next=element('section',null,'review-next');next.append(element('b','Your next step'),element('p',item.next_action));card.append(fields,next);
            if(item.due_date)card.append(element('p','Claimed due date: '+item.due_date+(item.overdue_claim?' · Past this date; confirm the obligation first.':'')));
            if(item.checks.length){const checks=element('ul',null,'review-checks');item.checks.forEach(reason=>checks.append(element('li',reviewReasons[reason]||reason)));card.append(checks);}
            const evidence=element('details');evidence.append(element('summary','Show matching evidence and limits'));item.document_ids.forEach(id=>{const record=board.documents.find(d=>d.review_id===id);if(!record)return;const f=record.analysis.facts;evidence.append(element('h4',record.filename),element('p',f.document_kind+' · '+f.summary),element('p','Recipient claim: '+(f.payee||'Not supplied')+' · Currency label: '+(f.currency_label||'Not supplied')),element('p','Arithmetic: '+record.analysis.arithmetic+' · '+record.provenance.mode));f.quotes.forEach(q=>evidence.append(element('blockquote',q.field+': “'+q.quote+'”')));});board.limits.forEach(limit=>evidence.append(element('p',limit,'screen-note')));card.append(evidence);
            const draft=element('details');draft.append(element('summary','Prepare a verification message'));const text=element('textarea');text.value=item.verification_draft;text.readOnly=true;text.className='goal';text.setAttribute('aria-label','Prepared verification message');draft.append(text,element('p','Prepared only. Send through a known official channel yourself; no complaint, refund or transfer has been submitted.','screen-note'));card.append(draft);reviewCards.append(card);
          });
        }catch(error){reviewStatus.textContent='Review unavailable: '+error.message+'. No payment was requested.';}finally{reviewRefresh.disabled=false;}}
      reviewRefresh.addEventListener('click',refreshReviews);
      const csvPanel=element('details',null,'simple-fold');csvPanel.append(element('summary','Match a transaction CSV (optional)'));const csvBody=element('div');const csvFile=element('input');csvFile.type='file';csvFile.accept='.csv,text/csv';csvFile.setAttribute('aria-label','Choose an INR CSV for financial reconciliation');const csvConsent=element('input');csvConsent.type='checkbox';const csvLabel=element('label',' Store parsed transaction claims in my private review inbox (raw CSV is discarded; no AI call)');csvLabel.prepend(csvConsent);const csvImport=element('button','Import transaction claims','planner');csvImport.type='button';csvBody.append(element('p','Up to 20 INR rows. Required: date,description,debit,credit. For exact bill matching add supplier,bill_reference,payee,transaction_reference. Missing identifiers remain unmatched.'),csvFile,csvLabel,csvImport);csvPanel.append(csvBody);reviewView.insertBefore(csvPanel,reviewCards);
      csvImport.addEventListener('click',()=>{if(!csvFile.files[0]||!csvConsent.checked){toast('Choose a CSV and confirm storage of parsed claims.');return;}const file=csvFile.files[0];if(file.size>1024*1024){toast('Use a CSV below 1 MB.');return;}reviewOperate(async()=>{await jsonRequest('/api/friday/reviews/statement','POST',{csv_text:await file.text(),confirm_store_claims:true});csvFile.value='';csvConsent.checked=false;await refreshReviews();},'Matching your user-supplied CSV claims - no payment or AI call.');});
      const priorReviewShow=show;show=function(name,push=true){priorReviewShow(name,push);if(name==='review'&&!busy)refreshReviews();};
      const sandboxMode=element('input');sandboxMode.type='checkbox';sandboxMode.id='review-sandbox-mode';
      const sandboxLabel=element('label',' Use original artificial-payment workflow (requires provider setup; may execute under saved rules)');sandboxLabel.prepend(sandboxMode);bill.append(sandboxLabel);
      async function reviewOperate(fn,label){if(busy){toast('Wait for Friday to finish the current task.');return;}busy=true;show('review');reviewStatus.textContent=label;try{await fn();}catch(error){reviewStatus.textContent='Review could not complete: '+error.message+'. No payment was requested. You can refresh the inbox to check whether extraction was saved.';}finally{busy=false;}}
      const originalPaymentCheck=checkLive;checkLive=()=>{if(sandboxMode.checked)return originalPaymentCheck();const text=$('live-input').value.trim();if(!text){toast('Paste a bill, receipt or payment notice first.');return Promise.resolve();}return reviewOperate(async()=>{const result=await jsonRequest('/api/friday/reviews','POST',{text});if(result.money_moved!==false||result.payment_authorized!==false)throw new Error('Unexpected authority');await refreshReviews();toast(result.reused?'Opened the existing review':'Financial input reviewed; no payment');},'Reading your financial input - no payment permission.');};
      sandboxMode.addEventListener('change',()=>{$('check-live').textContent=sandboxMode.checked?'Check & handle artificial bill':'Review this financial input';});$('check-live').textContent='Review this financial input';
      checkDocument=()=>{const file=$('document-input').files[0];if(!file){toast('Choose an image or PDF first.');return Promise.resolve();}return reviewOperate(async()=>{const response=await fetch('/api/friday/reviews/documents?filename='+encodeURIComponent(file.name),{method:'POST',headers:{'Content-Type':file.type||'application/octet-stream'},body:file});const result=await response.json();if(!response.ok)throw new Error(result.detail||'Review unavailable');if(result.money_moved!==false||result.payment_authorized!==false)throw new Error('Unexpected authority');await refreshReviews();toast(result.reused?'Opened the existing document review':'Document reviewed - no payment');},'Reading document claims with Gemini. No payment will be submitted.');};
      command.addEventListener('submit',()=>{sandboxMode.checked=false;$('check-live').textContent='Review this financial input';},true);
      $('check-document').textContent='Read & reconcile - no payment';
      $('document-input').setAttribute('aria-label','Choose a bill or receipt image or PDF for read-only review');
      const reviewDisclaimer=element('p','Read-only review. Uses Gemini on Google Cloud. Raw uploads are discarded; extracted facts remain private to your workspace. No provider setup or automatic-payment permission is needed.','screen-note');
      const uploadPrivacy=element('details',null,'simple-fold task-form');uploadPrivacy.append(element('summary','Privacy & what this check can prove'));const privacyBody=element('div');doc.querySelectorAll(':scope > .screen-note').forEach(note=>privacyBody.append(note));privacyBody.append(reviewDisclaimer);uploadPrivacy.append(privacyBody);doc.append(uploadPrivacy);
      const uploadFlow=element('ol',null,'friday-flow');['Choose a bill or receipt','Read with Gemini','Review facts & next steps'].forEach((text,index)=>uploadFlow.append(element('li',(index+1)+'. '+text)));doc.insertBefore(uploadFlow,docCard);const uploadExpectation=element('p','You’ll get extracted amounts, recipient claims, mismatches and a verification draft in your Financial inbox. An uploaded receipt is not proof of bank settlement.','screen-note');docCard.append(uploadExpectation);
      const commandButton=home.querySelector('button[type="submit"]');if(commandButton)commandButton.textContent='Review with Friday';
      home.querySelectorAll('p').forEach(p=>{if(p.textContent.includes('Checking can execute'))p.textContent='Review is read-only. Friday will not pay from this command.';});
      $('home-command').placeholder='Paste a bill, payment receipt or transaction notice. Friday will reconcile it without paying.';
      const inboxLink=element('button','Open my financial inbox','planner');inboxLink.type='button';inboxLink.dataset.screenLink='review';tiles.prepend(inboxLink);
      inboxLabel.textContent='Your financial inbox';everydayInbox.setAttribute('aria-label','Read-only financial inbox');rulesArea.hidden=true;everydayWarning.hidden=true;
      everydayIntroCopy.textContent='Bring your bills and receipts. Friday connects the evidence and prepares your next step without paying.';
      refreshEverydayHome=async()=>{
        if(everydayPreviewBusy)return;everydayPreviewBusy=true;everydayStatus.textContent='Loading your financial review…';
        try{const board=await jsonRequest('/api/friday/reviews');if(board.scope!=='READ_ONLY_FINANCIAL_REVIEW'||board.money_moved!==false||board.payment_authorized!==false)throw new Error('Unexpected scope');
          inboxCount.textContent=board.document_count+' saved input'+(board.document_count===1?'':'s');everydayRows.replaceChildren();
          if(!board.cases.length)everydayRows.append(element('p','Your private inbox is ready. Choose a starting task above; example checks appear here only after you run them.','everyday-empty'));
          board.cases.slice(0,3).forEach(item=>{const row=element('div',null,'money-row');const copy=element('div');copy.append(element('b',item.supplier||'Financial input'),element('small',reviewLabels[item.state]||'Needs review'));const open=element('button','Review evidence','planner');open.type='button';open.dataset.screenLink='review';row.append(copy,open);everydayRows.append(row);});
          everydayStatus.textContent='Document claims, not bank settlement. Payment execution is a separate artificial-money demo.';
        }catch(error){everydayRows.replaceChildren();inboxCount.textContent='Unavailable';everydayStatus.textContent='Inbox unavailable. No result or payment is assumed.';}
        finally{everydayPreviewBusy=false;}
      };
      const existingHelp=guide.querySelector('ol');if(existingHelp)existingHelp.innerHTML='<li><b>Review your own documents.</b> Add a bill and receipt; no artificial provider setup is needed.</li><li><b>Check the evidence.</b> Friday groups related claims, checks arithmetic and highlights conflicting recipients, amounts and payment references.</li><li><b>Take an informed next step.</b> Read the prepared verification message. Review never pays or confirms bank settlement. Sandbox execution is a separate explicit mode.</li>';
      titles.review='Your financial inbox';
"""
